mapper.select:
SELECT * FROM knowledge
WHERE status = 'ACTIVE' AND user_id = #{userId}
ORDER BY created_at DESC

mapper.update:
UPDATE knowledge set title = #{title},content = #{content},source = #{source},
                     category = #{category},tags = #{tags},star_rating=#{starRating},
                     ai_score = #{aiScore},personal_note = #{personalNote},
                     status = #{status},updated_at = #{updatedAt}
WHERE id = #{id} AND user_id = #{userId}
